package com.friendoncampus.order.config;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.core.annotation.Order;import org.springframework.http.HttpMethod;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import com.friendoncampus.order.web.error.ProblemSecurityHandler;
@Configuration public class InternalSecurityConfiguration {
 @Bean @Order(1) SecurityFilterChain internalOrders(HttpSecurity http,@Value("${app.service-auth.trusted-keys:{}}")String trust,ProblemSecurityHandler errors)throws Exception{return http.securityMatcher("/internal/**").csrf(AbstractHttpConfigurer::disable).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.GET,"/internal/orders/orders/*/evidence","/internal/orders/*/evidence").authenticated().anyRequest().denyAll()).oauth2ResourceServer(o->o.authenticationEntryPoint(errors).accessDeniedHandler(errors).jwt(j->j.decoder(new ServiceTokenDecoder("order-service",trust)::decode))).build();}
}
